package com.franco.desco.domain.campaignparticipant;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class CampaignParticipantModels{private CampaignParticipantModels(){}public record Summary(Long participacionId,Long campaniaVentaId,String estadoParticipacion,Instant fechaRegistro,Long socioId,String numeroDocumento,String socioNombre,Long operativos,Long entregasConfirmadas){}public record Operation(Long operativoSocioId,Long operativoVentaId,String codigo,String estadoOperativo,String estadoParticipacion){}public record Delivery(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String estadoProceso){}public record Detail(Long participacionId,String estadoParticipacion,Instant fechaRegistro,Long campaniaVentaId,String campania,Long socioId,String numeroDocumento,String socioNombre,List<Operation>operativos,List<Delivery>entregas){public Detail{operativos=operativos==null?List.of():List.copyOf(operativos);entregas=entregas==null?List.of():List.copyOf(entregas);}}}
